"    // Block credit checkout if no customer is selected
    const isCreditCheckout = method.toLowerCase() === 'credit' || (method.toLowerCase() === 'split' && parseFloat(splitCreditAmount) > 0);
    const tempFullPhone = customerPhone ? (customerPhone.startsWith('+') ? customerPhone : customerCountryCode + customerPhone) : '';
    if (isCreditCheckout && !tempFullPhone) {
      return toast.error("Customer must be selected for Credit payment!");
    }

    // Check if customer details are mandatory for PickUp & Delivery
    const isPickupDeliveryMandatory = !!business?.business_details?.settings?.custDetailsMandatoryForPickupDelivery;
    const isPickupOrDelivery = orderType === 'PICKUP' || orderType === 'DELIVERY';
    if (isPickupDeliveryMandatory && isPickupOrDelivery) {
      if (!customerName || !customerName.trim() || customerName.trim() === "POS Guest") {
        return toast.warning("Customer Name is mandatory for PickUp & Delivery orders!");
      }
      if (!customerPhone || !customerPhone.trim()) {
        return toast.warning("Customer Phone is mandatory for PickUp & Delivery orders!");
      }
    }"

